def solve(g):
    from collections import Counter
    h,w=len(g),len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    out=[[bg]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                comp=[(i,j)]; seen[i][j]=True; k=0
                while k<len(comp):
                    y,x=comp[k]; k+=1
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]!=bg:
                            seen[ny][nx]=True; comp.append((ny,nx))
                if len(comp)>=5:
                    c=Counter(g[y][x] for y,x in comp).most_common(1)[0][0]
                    cells=[(y,x) for y,x in comp if g[y][x]==c]
                    rcts=Counter(y for y,x in cells); ccts=Counter(x for y,x in cells)
                    mrr,mcc=max(rcts.values()),max(ccts.values())
                    rows={y for y,n in rcts.items() if n>=0.5*mrr}
                    cols={x for x,n in ccts.items() if n>=0.5*mcc}
                    for y in rows:
                        for x in cols: out[y][x]=c
    return out
